import java.util.*;

class Solution {
  private static final long EMPTY = Long.MIN_VALUE;
  private int n, block, mask;
  private long[] value, lazy;
  private long[][] keys; // per block: open-addressing table of values (without the block's lazy add)
  private int[][] counts;

  public int[] numberOfPairs(int[] nums1, int[] nums2, int[][] queries) {
    n = nums2.length;
    block = Math.max(1, (int) Math.sqrt(3.0 * n)); // balances ~2*block per update against ~5*n/block per query
    int blocks = (n + block - 1) / block, cap = 1;
    while (cap < 2 * block) cap <<= 1;
    mask = cap - 1;
    value = new long[n];
    lazy = new long[blocks];
    keys = new long[blocks][cap];
    counts = new int[blocks][cap];
    for (int i = 0; i < n; i++) value[i] = nums2[i];
    for (int b = 0; b < blocks; b++) rebuild(b);
    int total = 0;
    for (int[] q : queries) if (q[0] == 2) total++;
    int[] ans = new int[total];
    int idx = 0;
    for (int[] q : queries) {
      if (q[0] == 1) {
        int x = q[1], y = q[2], val = q[3], bx = x / block, by = y / block;
        if (bx == by) addRange(bx, x, y, val);
        else {
          addRange(bx, x, (bx + 1) * block - 1, val);
          for (int b = bx + 1; b < by; b++) lazy[b] += val;
          addRange(by, by * block, y, val);
        }
      } else {
        int count = 0;
        for (int a : nums1) {
          long want = (long) q[1] - a;
          for (int b = 0; b < blocks; b++) count += get(b, want - lazy[b]);
        }
        ans[idx++] = count;
      }
    }
    return ans;
  }

  private void addRange(int b, int from, int to, int val) {
    for (int i = from; i <= to; i++) value[i] += val;
    rebuild(b);
  }

  // rebuilding the whole block keeps the table free of stale zero-count keys
  private void rebuild(int b) {
    long[] k = keys[b];
    int[] c = counts[b];
    Arrays.fill(k, EMPTY);
    Arrays.fill(c, 0);
    for (int i = b * block, end = Math.min(n, (b + 1) * block); i < end; i++) {
      int s = slot(k, value[i]);
      k[s] = value[i];
      c[s]++;
    }
  }

  private int get(int b, long key) {
    int s = slot(keys[b], key);
    return keys[b][s] == key ? counts[b][s] : 0;
  }

  private int slot(long[] k, long key) {
    long h = key * 0x9E3779B97F4A7C15L;
    int s = (int) (h ^ (h >>> 32)) & mask;
    while (k[s] != EMPTY && k[s] != key) s = (s + 1) & mask;
    return s;
  }
}
